// 26a - Record outgoing customer message before attempting Meta API.
// Same incoming WhatsApp message ID must never create two normal replies.
const x=$input.first().json;
const inbound=$('04 - Parse Inbound').first().json;
if(!x.waPayload || !x.phone || !inbound.messageId)return [];
const mem=$getWorkflowStaticData('global');mem.outbox??={};mem.sessions??={};
const s=mem.sessions[x.phone];
const key='wa:'+inbound.messageId;
const prior=mem.outbox[key];
if(prior)return []; // includes sent, retry queued, review, cancelled and sending
const now=Date.now();
mem.outbox[key]={key,phone:x.phone,messageId:inbound.messageId,sessionId:s?.sessionId||'',payload:x.waPayload,status:'sending',attempts:1,createdAt:now,updatedAt:now,nextRetryAt:0,error:''};
if(s)s.pendingCustomerMessage=key;
// Keep the owner's notification AFTER customer attempt; do not block fast replies.
const route=$('08 - Main Menu + Navigation Logic').first().json;
const adminAlertPayload=x.adminAlertPayload||route.adminAlertPayload||inbound.adminAlertPayload||null;
return [{json:{...x,sendKey:key,adminAlertPayload}}];

// 26b - Record Meta outcome; retry only failures known to happen BEFORE a network send (DNS resolution).
const mem=$getWorkflowStaticData('global');mem.outbox??={};
const ctx=$('26a - Queue Customer Reply').first().json;
const job=mem.outbox[ctx.sendKey];
const res=$input.first()?.json||{};
const now=Date.now();
const msgId=res.messages?.[0]?.id||'';
const e=res.error||res;
const errorText=typeof e==='string'?e:JSON.stringify(e);
const isDnsFailure=/EAI_AGAIN|DNS server returned an error|[Gg]etaddrinfo EAI_AGAIN/.test(errorText);
let status='review';
if(job){
 if(msgId){status='sent';job.status='sent';job.wamid=msgId;job.error='';}
 else if(isDnsFailure){status='retry';job.status='retry';job.nextRetryAt=now+60000;job.error='EAI_AGAIN';}
 else{status='review';job.status='review';job.error=errorText.slice(0,300);}
 job.updatedAt=now;
 const s=mem.sessions?.[ctx.phone];
 if(s && s.pendingCustomerMessage===job.key){
   if(status!=='retry')s.pendingCustomerMessage=null;
   if(status==='sent'&&s.sessionId===job.sessionId&&s.lastInboundMessageId===job.messageId&&s.promptAt){s.promptAt=now;s.nudged=false;}
 }
}
return [{json:{phone:ctx.phone,sendKey:ctx.sendKey,sendStatus:status,adminAlertPayload:ctx.adminAlertPayload||null}}];

// Save provider result; only confirmed DNS-resolution failures may queue another attempt.
const mem=$getWorkflowStaticData('global');
const ctx=$('WA DNS - Permit One Authorized Retry').first().json;
const job=mem.outbox?.[ctx.sendKey];if(!job)return [];
const res=$input.first()?.json||{},wamid=res.messages?.[0]?.id||'';
const error=typeof res.error==='string'?res.error:JSON.stringify(res.error||res);
const now=Date.now();
if(wamid){job.status='sent';job.wamid=wamid;job.error='';}
else if(/EAI_AGAIN|DNS server returned an error|[Gg]etaddrinfo EAI_AGAIN/.test(error)&&job.attempts<5){
  job.status='retry';const gaps=[60000,180000,300000,600000];
  job.nextRetryAt=now+(gaps[Math.min(job.attempts-1,gaps.length-1)]||600000);job.error='EAI_AGAIN';
}else{job.status='review';job.error=error.slice(0,300);}
job.updatedAt=now;
const s=mem.sessions?.[job.phone];
if(s&&s.pendingCustomerMessage===job.key){
 if(job.status!=='retry')s.pendingCustomerMessage=null;
 if(job.status==='sent'&&s.sessionId===job.sessionId&&s.lastInboundMessageId===job.messageId&&s.promptAt){s.promptAt=now;s.nudged=false;}
}
return [{json:{kind:'dns',phone:job.phone,send_key:job.key,next_retry_at:job.nextRetryAt,job_status:job.status}}];

